import heapq
from typing import Dict, Optional, Set


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers: Dict[str, bool] = {}
        self._ticket_counter = 0

        # Stores metadata for each ticket:
        # ticket_id -> {"order": int, "priority_weight": int, "closed": bool}
        self._tickets: Dict[int, dict] = {}

        # Min-heap elements: (priority_rank, order, ticket_id)
        self._queue: list = []

        # Set of ticket IDs currently active in the queue
        self._in_queue: Set[int] = set()

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = vip

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        """Open a ticket; returns its id."""
        if not title:
            raise ValueError("Ticket title cannot be empty.")
        if priority not in self.PRIORITIES:
            raise ValueError(f"Invalid priority: {priority}")

        self._ticket_counter += 1
        ticket_id = self._ticket_counter

        # Critical (rank 0) > High (rank 1) > Normal (rank 2)
        priority_rank = -(self.PRIORITIES.index(priority))
        order = ticket_id

        self._tickets[ticket_id] = {
            "order": order,
            "priority_rank": priority_rank,
            "closed": False,
        }

        heapq.heappush(self._queue, (priority_rank, order, ticket_id))
        self._in_queue.add(ticket_id)

        return ticket_id

    def next_ticket(self) -> Optional[int]:
        """Take the ticket that should be handled next out of the queue; None if the queue is empty."""
        while self._queue:
            _, _, ticket_id = heapq.heappop(self._queue)
            if ticket_id in self._in_queue:
                self._in_queue.remove(ticket_id)
                return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        if ticket_id not in self._tickets:
            raise ValueError(f"Ticket {ticket_id} does not exist.")
        self._tickets[ticket_id]["closed"] = True
        self._in_queue.discard(ticket_id)

    def reopen(self, ticket_id: int) -> None:
        """Put a ticket back into the queue."""
        if ticket_id not in self._tickets:
            raise ValueError(f"Ticket {ticket_id} does not exist.")
        if self._tickets[ticket_id]["closed"]:
            raise ValueError(f"Cannot reopen closed ticket {ticket_id}.")

        if ticket_id not in self._in_queue:
            ticket_info = self._tickets[ticket_id]
            heapq.heappush(
                self._queue,
                (ticket_info["priority_rank"], ticket_info["order"], ticket_id),
            )
            self._in_queue.add(ticket_id)
